public class InnerHarnessHarnessMemoryConfigurationFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessMemoryConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessMemoryConfiguration>
{

    internal InnerHarnessHarnessManagedMemoryConfigurationFactory ManagedMemoryConfigurationFactory { get; set; }

    internal InnerHarnessHarnessAgentCoreMemoryConfigurationFactory AgentCoreMemoryConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessMemoryConfiguration Create()
    {
        var harnessMemoryConfigurationResult = CreateHarnessMemoryConfiguration();
        factoryAction?.Invoke(harnessMemoryConfigurationResult);

        return harnessMemoryConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessMemoryConfiguration CreateHarnessMemoryConfiguration()
    {
        var harnessMemoryConfigurationResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessMemoryConfiguration();

        return harnessMemoryConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessMemoryConfiguration result)
    {
        base.CreateChildren(result);

        result.ManagedMemoryConfiguration ??= ManagedMemoryConfigurationFactory?.Build();
        result.AgentCoreMemoryConfiguration ??= AgentCoreMemoryConfigurationFactory?.Build();
    }

} // End Of Class

